exercises.reference:
def compare(u, v):
    nodes = set(u) | set(v)
    u_le_v = all(u.get(n, 0) <= v.get(n, 0) for n in nodes)
    v_le_u = all(v.get(n, 0) <= u.get(n, 0) for n in nodes)
    if u_le_v and v_le_u:
        return "equal"
    if u_le_v:
        return "before"
    if v_le_u:
        return "after"
    return "concurrent"

